/**
 * @suppress
 */
public object FfiConverterTypeNativeLibrary: FfiConverter<NativeLibrary, Long> {
    override fun lower(value: NativeLibrary): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): NativeLibrary {
        return NativeLibrary(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): NativeLibrary {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: NativeLibrary) = 8UL

    override fun write(value: NativeLibrary, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



data class AccessRequest (
    val `id`: kotlin.String
    , 
    val `label`: kotlin.String
    , 
    val `kind`: MemberKind
    , 
    val `namespaces`: List<kotlin.String>
    , 
    val `access`: List<Access>
    , 
    val `pairingCode`: kotlin.String
    , 
    val `record`: kotlin.ByteArray
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAccessRequest: FfiConverterRustBuffer<AccessRequest> {
    override fun read(buf: ByteBuffer): AccessRequest {
        return AccessRequest(
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterTypeMemberKind.read(buf),
            FfiConverterSequenceString.read(buf),
            FfiConverterSequenceTypeAccess.read(buf),
            FfiConverterString.read(buf),
            FfiConverterByteArray.read(buf),
        )
    }

    override fun allocationSize(value: AccessRequest) = (
            FfiConverterString.allocationSize(value.`id`) +
            FfiConverterString.allocationSize(value.`label`) +
            FfiConverterTypeMemberKind.allocationSize(value.`kind`) +
            FfiConverterSequenceString.allocationSize(value.`namespaces`) +
            FfiConverterSequenceTypeAccess.allocationSize(value.`access`) +
            FfiConverterString.allocationSize(value.`pairingCode`) +
            FfiConverterByteArray.allocationSize(value.`record`)
    )

    override fun write(value: AccessRequest, buf: ByteBuffer) {
            FfiConverterString.write(value.`id`, buf)
            FfiConverterString.write(value.`label`, buf)
