enum class Access {
    
    READ,
    WRITE;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeAccess: FfiConverterRustBuffer<Access> {
    override fun read(buf: ByteBuffer) = try {
        Access.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: Access) = 4UL

    override fun write(value: Access, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}







sealed class BindingException: kotlin.Exception() {
    
    class InvalidData(
        
        val `detail`: kotlin.String
        ) : BindingException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class KeyProvider(
        
        val `detail`: kotlin.String
        ) : BindingException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
